#include "studio.hpp"
#include "lota/platform.hpp"
#include <iostream>
#include <filesystem>
int main(int argc,char **argv){try{auto base=std::filesystem::path(lota::defaultProjectPath()).parent_path().parent_path().parent_path();std::string path=(base/"project.lota").string(),capture,save,scene;int ticks=0;bool check=false;for(int i=1;i<argc;i++){std::string a=argv[i];auto value=[&](){if(++i>=argc)throw std::runtime_error("Missing value");return std::string(argv[i]);};if(a=="--project")path=value();else if(a=="--scene")scene=value();else if(a=="--capture")capture=value();else if(a=="--ticks")ticks=std::stoi(value());else if(a=="--validate")check=true;else throw std::runtime_error("Unknown option");}lota::StudioGame game(path);if(!scene.empty()){if(!game.project.scenes.count(scene))throw std::runtime_error("Unknown playtest map");game.scene=scene;game.feet=game.project.scenes.at(scene).spawn;}if(check||!capture.empty()){lota::Input input;input.set(lota::Action::Right,true);for(int i=0;i<ticks;i++){game.update(input,lota::Tick);input.consume();}if(!capture.empty()){lota::SoftwareRenderer r;r.render(game.draw(),game.atlas);r.writePPM(capture);}std::cout<<"Project validated: "<<game.project.scenes.size()<<" maps, "<<game.clips.size()<<" clips\n";return 0;}auto platform=lota::createPlatform(game.atlas,game.project.title);if(!game.audioAssets.empty()&&!platform->audioAvailable())std::cerr<<"Audio device unavailable; continuing silently.\n";save=platform->savePath(game.project.id);lota::Input input;double previous=platform->seconds(),accumulator=0;while(!game.quit&&platform->poll(input)){double now=platform->seconds();game.frameMs=float((now-previous)*1000);accumulator+=std::clamp(now-previous,0.,.1);previous=now;while(accumulator>=lota::Tick){game.update(input,lota::Tick);std::string error;if(input.hit(lota::Action::Save)&&!game.save(save,error))std::cerr<<error<<'\n';if(input.hit(lota::Action::Load)&&!game.load(save,error))std::cerr<<error<<'\n';input.consume();accumulator-=lota::Tick;}platform->setMusic(game.music(),game.musicVolume);for(auto &id:game.soundEvents)platform->playSound(game.audioAssets.at(id),game.sfxVolume);game.soundEvents.clear();platform->present(game.draw());platform->idle();}return 0;}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}}
